",null],["jobs","bigint",true,"","","0"],["failed_jobs","bigint",true,"","","0"],["artifacts","bigint",true,"","","0"],["stored_bytes","bigint",true,"","","0"]],"constraints":[["provider_snapshot_storage_usage_artifacts_check","c","CHECK (artifacts >= 0)",true,false,false],["provider_snapshot_storage_usage_failed_jobs_check","c","CHECK (failed_jobs >= 0)",true,false,false],["provider_snapshot_storage_usage_jobs_check","c","CHECK (jobs >= 0)",true,false,false],["provider_snapshot_storage_usage_pkey","p","PRIMARY KEY (storage_class)",true,false,false],["provider_snapshot_storage_usage_storage_class_check","c","CHECK (storage_class = ANY (ARRAY['hot'::text, 'history'::text]))",true,false,false],["provider_snapshot_storage_usage_stored_bytes_check","c","CHECK (stored_bytes >= 0)",true,false,false]],"indexes":[["private.provider_snapshot_storage_usage_pkey","CREATE UNIQUE INDEX provider_snapshot_storage_usage_pkey ON private.provider_snapshot_storage_usage USING btree (storage_class)",true,true,true,true,true]],"triggers":[],"policies":0,"inheritance":0},{"name":"private.provider_snapshot_targets","relkind":"r","relrowsecurity":true,"relforcerowsecurity":false,"owner":"postgres","acl":"{postgres=arwdDxtm/postgres}","columns":[["platform_id","uuid",true,"","",null],["target","jsonb",true,"","",null],["enabled","boolean",true,"","","true"],["updated_at","timestamp with time zone",true,"","","clock_timestamp()"]],"constraints":[["provider_snapshot_targets_pkey","p","PRIMARY KEY (platform_id)",true,false,false],["provider_snapshot_targets_target_check","c","CHECK (jsonb_typeof(target) = 'object'::text)",true,false,false]],"indexes":[["private.provider_snapshot_targets_pkey","CREATE UNIQUE INDEX provider_snapshot_targets_pkey ON private.provider_snapshot_targets USING btree (platform_id)",true,true,true,true,true]],"triggers":[],"policies":0,"inheritance":0}]$tables_rollback_before$::jsonb then raise exception using errcode='55000',message='snapshot_retention_rollback_before_